from django import forms
from django.utils.html import escape
from django.forms.utils import ErrorList
from django.core.exceptions import ValidationError
from django.utils.translation import ugettext_lazy as _

from booktype.utils.misc import booktype_slugify
from booki.editor.models import BookiGroup

from booktype.utils import misc
from booktype.apps.core.forms import BaseBooktypeForm

from widgets import RemovableImageWidget


class SpanErrorList(ErrorList):
    def __unicode__(self):
        return unicode(self.as_spans())

    def as_spans(self):
        return "<span style='color: red'>%s</span>" % (
            ",".join([e for e in self])
        )

class BaseGroupForm(BaseBooktypeForm, forms.ModelForm):
    name = forms.CharField()
    description = forms.CharField(
        label=_('Description (250 characters)'),
        required=False,
        max_length=250,
        widget=forms.Textarea(attrs={'rows': '10', 'cols': '40'})
    )
    group_image = forms.FileField(
        label=_('Group image'),
        required=False,
        widget=RemovableImageWidget(attrs={
                'label_class': 'checkbox-inline',
                'input_class': 'group-image-removable'
            }
        )
    )

    class Meta:
        model = BookiGroup
        fields = [
            'name', 'description'
        ]

    def __init__(self, *args, **kwargs):
        kwargs.update({'error_class': SpanErrorList})
        super(BaseGroupForm, self).__init__(*args, **kwargs)

    def clean_name(self):
        new_url_name = booktype_slugify(self.cleaned_data['name'])
        group_data_url_name = BookiGroup.objects.filter(url_name=new_url_name).exclude(pk=self.instance.pk)

        if len(group_data_url_name) > 0:
            raise ValidationError(_('Group name is already in use'))

        return self.cleaned_data.get('name', '')

    def clean_description(self):
        return escape(self.cleaned_data.get('description', ''))

    def set_group_image(self, group_id, group_image):
        try:
            filename = misc.set_group_image(group_id, group_image, 240, 240)

            if len(filename) == 0:
                raise ValidationError(_('Only JPEG file is allowed for group image.'))
            else:
                misc.set_group_image( "{}_small".format(group_id), group_image, 18, 18)
        except Exception as err:
            # TODO: we should do something here
            print err


class GroupCreateForm(BaseGroupForm):
    pass

class GroupUpdateForm(BaseGroupForm):

    def clean_group_image(self):
        group_image = self.files.get('group_image', None)
        group_id = str(self.instance.pk)

        if group_image:
            self.set_group_image(group_id, group_image)
        return group_image

import json
import random
import ssl
import string
import threading
import time
import websocket

import settings
from player import Player


class WebsocketPlayerControl(object):

    def __init__(self, player, server=settings.WS_SERVER):
        websocket.enableTrace(settings.DEBUG)
        rand_chars = string.ascii_uppercase + string.digits
        self.player_id = ''.join(random.choice(rand_chars) for _ in range(10))
        self.player = player
        self.ws = websocket.WebSocketApp(server,
                                         on_open=self.on_open,
                                         on_message=self.on_message,
                                         on_error=self.on_error)

        player.song_change_callback = self.song_change

    def song_change(self, identifier):
        data = {
            'action': 'song_change',
            'player': self.player_id,
            'key': settings.CLIENT_TOKEN,
            'playlist': settings.PLAYLIST_ID,
            'identifier': identifier
            }
        self.ws.send(json.dumps(data))

    def start(self):
        while True:
            if settings.DEBUG:
                print('opening websocket connection...')
            sslopt = {"cert_reqs": ssl.CERT_NONE}
            self.ws.run_forever(ping_interval=60, sslopt=sslopt)
            time.sleep(10)

    def quit(self):
        self.ws.send("client disconnect")
        self.ws.close()

    def on_open(self, ws):
        try:
            name = settings.CLIENT_NAME
        except AttributeError:
            name = 'Client'

        data = {
            'action': 'register',
            'player': self.player_id,
            'key': settings.CLIENT_TOKEN,
            'playlist': settings.PLAYLIST_ID,
            'name': name
            }
        ws.send(json.dumps(data))

    def on_message(self, ws, message):
        if settings.DEBUG:
            print('message received:', message)
        data = json.loads(message)

        if data['action'] == 'play':
            self.player.play()
        elif data['action'] == 'pause':
            self.player.pause()
        elif data['action'] == 'update_playlist':
            self.player.update_playlist()
        elif data['action'] == 'next':
            self.player.next()
        elif data['action'] == 'play_song':
            self.player.play_song(data['identifier'])

    def on_error(self, ws, error):
        print(error)


def main():
    player = Player()
    ws = WebsocketPlayerControl(player)

    ws_thread = threading.Thread(name='ws', target=ws.start)

    try:
        ws_thread.start()
        player.start()
    except KeyboardInterrupt:
        player.quit()
        ws.quit()
        ws_thread.join()


if __name__ == "__main__":
    main()

