import logging

import numpy as np
from numpy import ma

from cotede.qctests import QCCheckVar

try:
    import pandas as pd

    PANDAS_AVAILABLE = True
except ImportError:
    PANDAS_AVAILABLE = False

module_logger = logging.getLogger(__name__)


def gradient(x):
    return curvature(x)


def _curvature_pandas(x):
    """Equivalent to curvature() but using pandas

    It looks like the numpy implementation is faster even for larger datasets,
    so the default is with numpy.

    Note
    ----
    - In the future this will be useful to handle specific window widths.
    """
    if isinstance(x, ma.MaskedArray):
        x[x.mask] = np.nan
        x = x.data

    if not PANDAS_AVAILABLE:
        return curvature(x)

    if hasattr(x, "to_series"):
        x = x.to_series()
    elif not isinstance(x, pd.Series):
        x = pd.Series(x)

    y = np.nan * x
    y = x - (x.shift(1) + x.shift(-1)) / 2.0
    return np.array(y)


def curvature(x):
    """Curvature of a timeseries

    This test is commonly known as gradient for historical reasons, but that
    is a bad name choice since it is not the actual gradient, like:
    d/dx + d/dy + d/dz,
    but as defined by GTSPP, EuroGOOS and others, which is actually the
    curvature of the timeseries..

    Note
    ----
    - Pandas.Series operates with indexes, so it should be done different. In
      that case, call for _curvature_pandas.
    """
    if isinstance(x, ma.MaskedArray):
        x[x.mask] = np.nan
        x = x.data

    if PANDAS_AVAILABLE and isinstance(x, pd.Series):
        return _curvature_pandas(x)

    x = np.atleast_1d(x)
    y = np.nan * x
    y[1:-1] = x[1:-1] - (x[:-2] + x[2:]) / 2.0
    return y


class Gradient(QCCheckVar):
    def set_features(self):
        self.features = {"gradient": curvature(self.data[self.varname])}

    def test(self):
        self.flags = {}
        try:
            threshold = self.cfg["threshold"]
        except KeyError:
            module_logger.debug(
                "Deprecated cfg format. It should contain a threshold item."
            )
            threshold = self.cfg

        assert (
            (np.size(threshold) == 1)
            and (threshold is not None)
            and (np.isfinite(threshold))
        )

        flag = np.zeros(np.shape(self.data[self.varname]), dtype="i1")
        feature = np.absolute(self.features["gradient"])
        flag[feature > threshold] = self.flag_bad
        flag[feature <= threshold] = self.flag_good
        x = np.atleast_1d(self.data[self.varname])
        flag[ma.getmaskarray(x) | ~np.isfinite(x)] = 9
        self.flags["gradient"] = flag

from twisted.plugin import IPlugin
from twisted.words.protocols import irc
from txircd.config import ConfigValidationError
from txircd.module_interface import Command, ICommand, IModuleData, ModuleData
from txircd.utils import trimStringToByteLength
from zope.interface import implementer
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

@implementer(IPlugin, IModuleData, ICommand)
class AwayCommand(ModuleData, Command):
	name = "AwayCommand"
	core = True

	def userCommands(self) -> List[Tuple[str, int, Command]]:
		return [ ("AWAY", 1, self) ]

	def actions(self) -> List[Tuple[str, int, Callable]]:
		return [ ("commandextra-PRIVMSG", 10, self.notifyAway),
		         ("commandextra-NOTICE", 10, self.notifyAway),
		         ("extrawhois", 10, self.addWhois),
		         ("buildisupport", 1, self.buildISupport),
		         ("usermetadataupdate", 10, self.sendAwayNotice) ]

	def verifyConfig(self, config: Dict[str, Any]) -> None:
		if "away_length" in config:
			if not isinstance(config["away_length"], int) or config["away_length"] < 0:
				raise ConfigValidationError("away_length", "invalid number")
			elif config["away_length"] > 200:
				config["away_length"] = 200
				self.ircd.logConfigValidationWarning("away_length", "value is too large", 200)

	def notifyAway(self, user: "IRCUser", data: Dict[Any, Any]) -> None:
		if "targetusers" not in data:
			return
		for u in data["targetusers"].keys():
			if u.metadataKeyExists("away"):
				user.sendMessage(irc.RPL_AWAY, u.nick, u.metadataValue("away"))

	def addWhois(self, user: "IRCUser", targetUser: "IRCUser") -> None:
		if targetUser.metadataKeyExists("away"):
			user.sendMessage(irc.RPL_AWAY, targetUser.nick, targetUser.metadataValue("away"))

	def buildISupport(self, data: Dict[str, Union[str, int]]) -> None:
		data["AWAYLEN"] = self.ircd.config.get("away_length", 200)

	def sendAwayNotice(self, user: "IRCUser", key: str, oldValue: str, value: str, fromServer: Optional["IRCServer"]) -> None:
		if key == "away":
			if value:
				user.sendMessage(irc.RPL_NOWAWAY, "You have been marked as being away")
			else:
				user.sendMessage(irc.RPL_UNAWAY, "You are no longer marked as being away")

	def parseParams(self, user: "IRCUser", params: List[str], prefix: str, tags: Dict[str, Optional[str]]) -> Optional[Dict[Any, Any]]:
		if not params:
			return {}
		message = " ".join(params)
		message = trimStringToByteLength(message, self.ircd.config.get("away_length", 200))
		return {
			"message": message
		}

	def execute(self, user: "IRCUser", data: Dict[Any, Any]) -> bool:
		if "message" in data and data["message"]:
			user.setMetadata("away", data["message"])
		else:
			user.setMetadata("away", None)
		return True

