"""Property classes for building wrapper classes for Pikov nodes.

We want to wrap our semantic graph with Python classes. This allows us to
interact with Python objects to modify the guid_map.

These classes encode the core types used in the semantic graph. When classes
use these properties, the guid_map is updated with the correct serialization
of the property.
"""

from .core import Int64Node, StringNode


class AbstractSemanticGraphProperty(object):
    def __init__(self, label):
        self._label = label

    def from_node(self, obj, value):
        raise NotImplementedError()

    def to_node(self, value):
        raise NotImplementedError()

    def __get__(self, obj, type=None):
        return self.from_node(obj, obj[self._label])

    def __set__(self, obj, value):
        obj[self._label] = self.to_node(value)


class UnspecifiedProperty(AbstractSemanticGraphProperty):
    def from_node(self, obj, value):
        obj._graph.get_value(obj, self._label)

    def to_node(self, value):
        # Value should already by a Node.
        return value


class GuidProperty(AbstractSemanticGraphProperty):
    def __init__(self, label, cls):
        super().__init__(label)
        self._cls = cls

    def from_node(self, obj, value):
        if value is None:
            return None
        return self._cls(obj._graph, guid=value.guid)

    def to_node(self, value):
        # Value should already by a GuidNode.
        return value


def make_guid_property(wrapped):
    def __init__(self, label):
        GuidProperty.__init__(self, label, wrapped)

    return type(
        wrapped.__name__ + "Property",
        (GuidProperty,),
        {
            "__init__": __init__,
        }
    )


class ScalarProperty(AbstractSemanticGraphProperty):
    def from_node(self, obj, value):
        if value is None:
            return None
        return value.value


class Int64Property(ScalarProperty):
    def to_node(self, value):
        if value is None:
            return None
        return Int64Node(value)


class StringProperty(ScalarProperty):
    def to_node(self, value):
        if value is None:
            return None
        return StringNode(value)

import boto,sys,euca_admin
from boto.exception import EC2ResponseError
from euca_admin.generic import BooleanResponse
from euca_admin.generic import StringList
from boto.resultset import ResultSet
from euca_admin import EucaAdmin
from optparse import OptionParser

SERVICE_PATH = '/services/Accounts'
class Group():


  def __init__(self, groupName=None):
    self.group_groupName = groupName
    self.group_users = StringList()
    self.group_auths = StringList()
    self.euca = EucaAdmin(path=SERVICE_PATH)

  def __repr__(self):
    r = 'GROUP      \t%s\t' % (self.group_groupName)
    r = '%s\nUSERS\t%s\t%s' % (r,self.group_groupName,self.group_users)
    r = '%s\nAUTH\t%s\t%s' % (r,self.group_groupName,self.group_auths)
    return r

  def startElement(self, name, attrs, connection):
    if name == 'euca:users':
      return self.group_users
    if name == 'euca:authorizations':
      return self.group_auths
    else:
      return None

  def endElement(self, name, value, connection):
    if name == 'euca:groupName':
      self.group_groupName = value
    else:
      setattr(self, name, value)

  def get_describe_parser(self):
    parser = OptionParser("usage: %prog [GROUPS...]",version="Eucalyptus %prog VERSION")
    return parser.parse_args()

  def cli_describe(self):
    (options, args) = self.get_describe_parser()
    self.group_describe(args)

  def group_describe(self,groups=None):
    params = {}
    if groups:
      self.euca.connection.build_list_params(params,groups,'GroupNames')
    try:
      list = self.euca.connection.get_list('DescribeGroups', params, [('euca:item', Group)])
      for i in list:
        print i
    except EC2ResponseError, ex:
      self.euca.handle_error(ex)

  def get_single_parser(self):
    parser = OptionParser("usage: %prog GROUPNAME",version="Eucalyptus %prog VERSION")
    (options,args) = parser.parse_args()    
    if len(args) != 1:
      print "ERROR  Required argument GROUPNAME is missing or malformed."
      parser.print_help()
      sys.exit(1)
    else:
      return (options,args)  

  def cli_add(self):
