import json
import bottle
from pyrouted.util import make_spec


def route(method, path):
    def decorator(f):
        f.http_route = path
        f.http_method = method
        return f
    return decorator


class APIv1(object):

    prefix = '/v1'

    def __init__(self, ndb, config):
        self.ndb = ndb
        self.config = config

    @route('GET', '/sources')
    def sources_list(self, mode='short'):
        ret = {}
        mode = bottle.request.query.mode or mode
        for name, spec in self.ndb.sources.items():
            ret[name] = {'class': spec.nl.__class__.__name__,
                         'status': spec.status}
            if mode == 'full':
                ret[name]['config'] = spec.nl_kwarg
        return bottle.template('{{!ret}}', ret=json.dumps(ret))

    @route('PUT', '/sources')
    def sources_restart(self):
        node = bottle.request.body.getvalue().decode('utf-8')
        self.ndb.sources[node].start()

    @route('POST', '/sources')
    def sources_add(self):
        data = bottle.request.body.getvalue().decode('utf-8')
        node, spec = make_spec(data, self.config)
        self.config['sources'].append(node)
        self.ndb.connect_source(node, spec)

    @route('DELETE', '/sources')
    def sources_del(self):
        node = bottle.request.body.getvalue().decode('utf-8')
        self.config['sources'].remove(node)
        self.ndb.disconnect_source(node)

    @route('GET', '/config')
    def config_get(self):
        return bottle.template('{{!ret}}',
                               ret=json.dumps(self.config))

    @route('PUT', '/config')
    def config_dump(self):
        path = bottle.request.body.getvalue().decode('utf-8')
        self.config.dump(path)

    @route('GET', '/<name:re:(%s|%s|%s|%s|%s|%s)>' % ('interfaces',
                                                      'addresses',
                                                      'routes',
                                                      'neighbours',
                                                      'vlans',
                                                      'bridges'))
    def view(self, name):
        ret = []
        obj = getattr(self.ndb, name)
        for line in obj.dump():
            ret.append(line)
        return bottle.template('{{!ret}}', ret=json.dumps(ret))

    @route('GET', '/query/<name:re:(%s|%s|%s|%s)>' % ('nodes',
                                                      'p2p_edges',
                                                      'l2_edges',
                                                      'l3_edges'))
    def query(self, name):
        ret = []
        obj = getattr(self.ndb.query, name)
        for line in obj():
            ret.append(line)
        return bottle.template('{{!ret}}', ret=json.dumps(ret))

import os
import signal
import subprocess


class Camera(object):

    # In order to run mjpg-streamer through Python, make sure
    # mjpg-streamer-experimental is installed so the .so objects
    # and mjpg-streamer are all on defualt PATH so we don't have
    # to specify path (was getting a lot of errors resulting from
    # files not being able to be found. Resolution must also be
    # specified in "integerxinteger" and not by name.

    # default layout for camera
    def __init__(self, resolution='1280x720', framerate=30, device='/dev/video0', port=8080, brightness=16, contrast=32):
        self.process = None
        self.resolution = resolution
        self.framerate = framerate
        self.device = device
        self.port = port
        self.brightness = brightness
        self.contrast = contrast

        self.input = 'input_uvc.so -d {device}'.format(
            device=self.device,
        )
        self.output = 'output_http.so -p {port} {web}'.format(
            port=self.port,
            web='-w /usr/local/www'
        )

        self.status = "killed"

    # framerate shouldn't be changed: keep at 30, allows for a good image while
    # reserving valuable processing power for other devices. Device is formatted as a
    # string: /dev/videoNUM where NUM is the number for the order in which camera is
    # plugged in, starting at 0. Port is the web port where you want to output image
    # to: change as needed

    # open video feed for an instance of Camera
    def start(self):
        self.process = subprocess.Popen(['mjpg_streamer', '-i', self.input, '-o', self.output])

        if self.is_alive():
            self.status = 'active'

    # closes video feed for an instance of Camera: each instance of Camera must be killed
    # using this method
    def kill(self):
        if self.is_alive():
            self.process.kill()
            self.status = 'killed'

    def suspend(self):
        os.kill(self.process.pid, signal.SIGSTOP)
        self.status = 'suspended'

    def unsuspend(self):
        if self.status == 'suspended':
            os.kill(self.process.pid, signal.SIGCONT)
            self.status = 'active'

    def is_alive(self):
        if self.process is None:
            return False
        return (self.process.poll() is None)

    def get_status(self):
        if not self.is_alive():
            self.status = 'killed'

        return self.status

    def set_status(self, status):
        if status == 'active':
            if self.status == 'suspended':
                self.unsuspend()
            elif self.status == 'killed':
                self.start()
        elif status == 'suspended':
            if self.status == 'active':
                self.suspend()
        elif status == 'killed':
            self.kill()

